require_once __DIR__.'/../includes/auth.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$phone=trim($_POST['phone']);db()->prepare('UPDATE users SET name=?,phone=? WHERE id=?')->execute([$name,$phone,user()['id']]);$_SESSION['user']['name']=$name;if(!empty($_POST['new_password'])){if(strlen($_POST['new_password'])<8){flash('warning','Password must be at least 8 characters.');}else{db()->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['new_password'],PASSWORD_BCRYPT),user()['id']]);flash('success','Profile and password updated.');}}else flash('success','Profile updated.');redirect('app/profile.php');}
