<div class="grid-2"><div class="profile-card"><div class="profile-cover"></div><div class="profile-info"><div class="profile-avatar"><?= e(initials($me['name'])) ?></div><h2 class="mt-3 mb-1" style="font-family:Manrope"><?= e($me['name']) ?></h2><p class="text-muted small"><?= e(ucwords(str_replace('_',' ',$me['role']))) ?> · <?= e($me['branch_name']) ?></p><div class="mini-list mt-4"><div class="mini-row"><div class="mini-avatar"><i class="fa-regular fa-envelope"></i></div><div class="grow"><strong>Email</strong><small><?= e($me['email']) ?></small></div></div><div class="mini-row"><div class="mini-avatar"><i class="fa-solid fa-phone"></i></div><div class="grow"><strong>Phone</strong><small><?= e($me['phone']) ?></small></div></div></div></div></div><div class="card-form"><h3 class="section-title">Account settings</h3><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="mb-3"><label class="form-label">Name</label><input name="name" value="<?= e($me['name']) ?>" class="form-control"></div><div class="mb-3"><label class="form-label">Phone</label><input name="phone" value="<?= e($me['phone']) ?>" class="form-control"></div><div class="mb-3"><label class="form-label">Email</label><input value="<?= e($me['email']) ?>" class="form-control" disabled></div><div class="mb-4"><label class="form-label">New password <span class="text-muted">(leave blank to keep current)</span></label><input type="password" name="new_password" class="form-control" placeholder="Minimum 8 characters"></div><button class="btn btn-primary">Save changes</button></form></div></div>
